B.WT=new A.n(B.f,["Ung\xfcltige Open-Prices-Antwort","Invalid Open Prices response","Risposta Open Prices non valida","Respuesta de Open Prices no v\xe1lida"],t.w)
B.TI=new A.n(B.f,["Overpass nicht verf\xfcgbar","Overpass unavailable","Overpass non disponibile","Overpass no disponible"],t.w)
B.W_=new A.n(B.f,["OpenStreetMap-Fehler: {c} {b}","OpenStreetMap error: {c} {b}","Errore OpenStreetMap: {c} {b}","Error de OpenStreetMap: {c} {b}"],t.w)
B.XL=new A.n(B.f,["Ung\xfcltige OpenStreetMap-Antwort","Invalid OpenStreetMap response","Risposta OpenStreetMap non valida","Respuesta de OpenStreetMap no v\xe1lida"],t.w)
B.Xz=new A.n(B.f,["Ung\xfcltiger OpenStreetMap-Typ","Invalid OpenStreetMap type","Tipo OpenStreetMap non valido","Tipo de OpenStreetMap no v\xe1lido"],t.w)
B.TN=new A.n(B.f,["Laden konnte in Open Prices nicht gepr\xfcft werden ({c}): {b}","Could not check the store in Open Prices ({c}): {b}","Impossibile verificare il negozio in Open Prices ({c}): {b}","No se pudo comprobar la tienda en Open Prices ({c}): {b}"],t.w)
