B.WN=new A.n(B.f,["Fehler bei der Routenberechnung: {c}","Route calculation error: {c}","Errore nel calcolo dell\u2019itinerario: {c}","Error al calcular la ruta: {c}"],t.w)
B.TS=new A.n(B.f,["Keine Stra\xdfenroute gefunden","No road route found","Nessun itinerario stradale trovato","No se encontr\xf3 ninguna ruta por carretera"],t.w)
