B.XP=new A.n(B.f,["Ung\xfcltige Stra\xdfenentfernung","Invalid road distance","Distanza stradale non valida","Distancia por carretera no v\xe1lida"],t.w)
B.WD=new A.n(B.f,["Open-Food-Facts-Fehler: {c}","Open Food Facts error: {c}","Errore Open Food Facts: {c}","Error de Open Food Facts: {c}"],t.w)
B.UG=new A.n(B.f,["Ung\xfcltige Open-Food-Facts-Antwort","Invalid Open Food Facts response","Risposta Open Food Facts non valida","Respuesta de Open Food Facts no v\xe1lida"],t.w)
B.US=new A.n(B.f,["Kein Produkt gefunden","No product found","Nessun prodotto trovato","No se encontr\xf3 ning\xfan producto"],t.w)
B.Xi=new A.n(B.f,["Nicht genug erfasste Preise ({n}) f\xfcr eine Vorhersage.","Not enough recorded prices ({n}) to predict.","Prezzi rilevati insufficienti ({n}) per una previsione.","No hay suficientes precios registrados ({n}) para predecir."],t.w)
B.UK=new A.n(B.f,["Kein Angebot in {n} Erfassungen: Preis eher stabil.","No deal seen in {n} records: price fairly stable.","Nessuna promozione vista su {n} rilevazioni: prezzo piuttosto stabile.","Ninguna oferta en {n} registros: precio bastante estable."],t.w)
B.U8=new A.n(B.f,["(oft bei {m})","(often at {m})","(spesso da {m})","(a menudo en {m})"],t.w)
B.YG=new A.n(B.f,["Nur ein Angebot beobachtet, am {d}{o}. Rhythmus noch unbekannt.","Only one deal seen, on {d}{o}. Pattern still unknown.","Una sola promozione osservata, il {d}{o}. Ritmo ancora sconosciuto.","Solo se ha visto una oferta, el {d}{o}. Ritmo a\xfan desconocido."],t.w)
B.VY=new A.n(B.f,["Angebot sehr bald erwartet (\xfcblicher Rhythmus \xfcberschritten)","Deal expected very soon (usual pattern exceeded)","Promozione attesa a breve (ritmo abituale superato)","Oferta esperada muy pronto (ritmo habitual superado)"],t.w)
B.YE=new A.n(B.f,["N\xe4chstes Angebot gesch\xe4tzt um den {d}","Next deal estimated around {d}","Prossima promozione stimata verso il {d}","Pr\xf3xima oferta estimada hacia el {d}"],t.w)
B.YA=new A.n(B.f,["{q}{o}. Etwa alle {i} Tage im Angebot ({n} Angebote beobachtet).","{q}{o}. On sale about every {i} days ({n} deals seen).","{q}{o}. In promozione circa ogni {i} giorni ({n} promozioni osservate).","{q}{o}. En oferta aproximadamente cada {i} d\xedas ({n} ofertas observadas)."],t.w)
B.UT=new A.n(B.f,["Angebot wahrscheinlich in {n} Tag","Deal likely within {n} day","Promozione probabile entro {n} giorno","Oferta probable en {n} d\xeda"],t.w)
B.Xf=new A.n(B.f,["Angebot wahrscheinlich in {n} Tagen","Deal likely within {n} days","Promozione probabile entro {n} giorni","Oferta probable en {n} d\xedas"],t.w)
B.Yb=new A.n(B.f,["Der lokale Speicher hat das Speichern abgelehnt.","Local storage refused to save.","La memoria locale ha rifiutato il salvataggio.","El almacenamiento local ha rechazado el guardado."],t.w)
B.Wi=new A.n(B.f,["Der Browser hat das Speichern der Einstellungen abgelehnt.","The browser refused to save the settings.","Il browser ha rifiutato il salvataggio delle impostazioni.","El navegador ha rechazado guardar los ajustes."],t.w)
